toad_implementation.code_blueprint:
canvas {
  size: 960px 600px;
  fill: #041008;
  font-family: "Share Tech Mono, monospace";
}

>nightVision = #041008;
>phosphor = #00FF66;
>threatRed = #FF3333;
>gridGreen = #00662A;

circle #radarSweepRing1 {
  at: center of canvas offset 0px -20px;
  size: 400px;
  fill: none;
  stroke: >gridGreen;
  stroke-width: 1px;
}

circle #radarSweepRing2 {
  at: center of canvas offset 0px -20px;
  size: 260px;
  fill: none;
  stroke: >gridGreen;
  stroke-width: 1px;
}

circle #targetLock {
  at: center of canvas offset 60px -80px;
  size: 48px;
  fill: none;
  stroke: >threatRed;
  stroke-width: 2px;
}

text #targetTag {
  at: right of #targetLock offset 12px 0px;
  content: "BOGEY #04 [HOSTILE]\nALT: 12,400 FT\nSPD: MACH 1.4";
  font-size: 11px;
  font-weight: 700;
  color: >threatRed;
}

rect #topHeadingTape {
  at: top center of canvas offset 0px 24px;
  size: 720px 32px;
  fill: #061B0E;
  stroke: >phosphor;
  stroke-width: 1px;
}

text #headingNumbers {
  at: center of #topHeadingTape;
  content: "030 • 045 • 060 • [ 075° ] • 090 • 105 • 120";
  font-size: 12px;
  font-weight: 700;
  color: >phosphor;
}

text #missionStatus {
  at: bottom left of canvas offset 40px -40px;
  content: "OPERATION NIGHTFALL // TASK FORCE OMEGA\nDEFCON 2 • STATUS: ARMED • TIME: 03:42:18 ZULU";
  font-size: 12px;
  font-weight: 700;
  color: >phosphor;
}
